/**
 * Regenerates assets.generated.ts from the browser modules in this folder (math.js, viewer.js, editor.js).
 * The kit serves them from that file so it runs anywhere (Workers has no filesystem) with no build step for users.
 *
 *   bun src/tour/client/embed.ts          (or: node --experimental-strip-types src/tour/client/embed.ts)
 *
 * test/tour/assets.test.ts fails when the generated file is stale.
 */
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
export const ASSET_FILES = ["math.js", "viewer.js", "editor.js"] as const;

/** The generated module's source for the current files. */
export function generateAssets(): string {
  const hashes: Record<string, string> = {};
  const out: Record<string, { body: string; hash: string }> = {};
  for (const name of ASSET_FILES) {
    // Pin relative imports to the dependency's content hash so long-lived caches never mix versions.
    const body = readFileSync(join(here, name), "utf8").replace(/from "\.\/([a-z]+\.js)"/g, (m, dep: string) =>
      hashes[dep] ? `from "./${dep}?v=${hashes[dep]}"` : m,
    );
    hashes[name] = createHash("sha256").update(body).digest("hex").slice(0, 16);
    out[name] = { body, hash: hashes[name]! };
  }
  return `// GENERATED by src/tour/client/embed.ts from ${ASSET_FILES.join(", ")} — do not edit; run \`bun src/tour/client/embed.ts\`.
export const ASSETS: Record<string, { body: string; hash: string }> = ${JSON.stringify(out, null, 1)};
`;
}

if (import.meta.main ?? process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(join(here, "assets.generated.ts"), generateAssets());
  console.log("wrote src/tour/client/assets.generated.ts");
}
